function otherSpending(entry){return typeof entry?.otherExpense==='number'&&Number.isFinite(entry.otherExpense)?entry.otherExpense:0}
function totalSpending(entry){return entry?.expense===null||entry?.expense===undefined?null:entry.expense+otherSpending(entry)}
