function dateSettings(profile,date){const events=profile.targetSchedule||[];if(!events.length)return profile;let settings={...profile,...events[0].changes};for(const event of [...events].sort((a,b)=>a.effectiveFrom.localeCompare(b.effectiveFrom))){if(event.effectiveFrom<=date)settings={...settings,...event.changes}}return settings}
function scheduledProfile(previous,next,effectiveFrom,today){const keys=['plan','study','budget','wake','bed','religion'];const pick=p=>Object.fromEntries(keys.map(key=>[key,structuredClone(p[key])]));const events=structuredClone(previous?.targetSchedule||[]);if(!events.length)events.push({effectiveFrom:today,changes:pick(previous||next)});const changes={};for(const key of keys)if(!previous||JSON.stringify(previous[key])!==JSON.stringify(next[key]))changes[key]=structuredClone(next[key]);if(Object.keys(changes).length){const found=events.find(event=>event.effectiveFrom===effectiveFrom);if(found)found.changes={...found.changes,...changes};else events.push({effectiveFrom,changes})}events.sort((a,b)=>a.effectiveFrom.localeCompare(b.effectiveFrom));return {...next,targetSchedule:events}}
